import { Injectable } from '@nestjs/common';
import {
    registerDecorator,
    ValidationArguments,
    ValidationOptions,
    ValidatorConstraint,
    ValidatorConstraintInterface,
} from 'class-validator';
import { OfferingType } from '../entities/OfferingType.js';
import { CreateOfferingDTO, ValidBillingCycles } from './createOffering.dto.js';

export const TOP_UP_AMOUNT_REQUIRED_MESSAGE = 'topUpAmount is required when the billingCycle is topUp';
export const TOP_UP_NOT_ALLOWED_ON_SUBSCRIPTION_MESSAGE =
    'The topUp billing cycle is not supported for subscription offerings';
export const TOP_UP_FIELDS_NOT_ALLOWED_MESSAGE =
    'topUpAmount and topUpThreshold are only allowed when the billingCycle is topUp';

/**
 * Validates the billing cycle of an offering.
 * When the billing cycle is `topUp` a `topUpAmount` must be provided,
 * and the offering cannot be a subscription offering.
 */
@ValidatorConstraint({ name: 'TopUpBillingCycleRule', async: false })
@Injectable()
export class TopUpBillingCycleRule implements ValidatorConstraintInterface {
    validate(billingCycle: ValidBillingCycles, args: ValidationArguments) {
        if (billingCycle !== ValidBillingCycles.topUp) {
            return true;
        }
        const { topUpAmount, offeringType } = args.object as CreateOfferingDTO;
        if (offeringType === OfferingType.subscription) {
            return false;
        }
        if (topUpAmount === undefined || topUpAmount === null || topUpAmount === '') {
            return false;
        }
        return true;
    }

    defaultMessage(args: ValidationArguments) {
        const { offeringType } = args.object as CreateOfferingDTO;
        if (offeringType === OfferingType.subscription) {
            return TOP_UP_NOT_ALLOWED_ON_SUBSCRIPTION_MESSAGE;
        }
        return TOP_UP_AMOUNT_REQUIRED_MESSAGE;
    }
}

export function TopUpBillingCycle(property: string, validationOptions?: ValidationOptions) {
    return function (object: unknown, propertyName: string) {
        registerDecorator({
            name: 'topUpBillingCycle',
            target: object.constructor,
            propertyName: propertyName,
            constraints: [property],
            options: validationOptions,
            validator: TopUpBillingCycleRule,
        });
    };
}

/**
 * Validates that the top up fields are only used on offerings with a `topUp` billing cycle.
 */
@ValidatorConstraint({ name: 'TopUpFieldsAllowedRule', async: false })
@Injectable()
export class TopUpFieldsAllowedRule implements ValidatorConstraintInterface {
    validate(value: string, args: ValidationArguments) {
        if (value === undefined || value === null) {
            return true;
        }
        const { billingCycle, offeringType } = args.object as CreateOfferingDTO;
        if (offeringType === OfferingType.subscription) {
            return false;
        }
        return billingCycle === ValidBillingCycles.topUp;
    }

    defaultMessage(args: ValidationArguments) {
        const { offeringType } = args.object as CreateOfferingDTO;
        if (offeringType === OfferingType.subscription) {
            return TOP_UP_NOT_ALLOWED_ON_SUBSCRIPTION_MESSAGE;
        }
        return TOP_UP_FIELDS_NOT_ALLOWED_MESSAGE;
    }
}

export function TopUpFieldsAllowed(property: string, validationOptions?: ValidationOptions) {
    return function (object: unknown, propertyName: string) {
        registerDecorator({
            name: 'topUpFieldsAllowed',
            target: object.constructor,
            propertyName: propertyName,
            constraints: [property],
            options: validationOptions,
            validator: TopUpFieldsAllowedRule,
        });
    };
}

