}

/**
 * Determines the wallet balance which is currently associated with a customer.
 */
public static getCustomerWalletBalance(customer?: ReadCustomerResponseData): number {
    const balance = parseFloat(customer?.creditBalance);
    return isNaN(balance) ? 0 : balance;
}

/**
 * The balance a customers wallet must drop below before the wallet is topped up again.
 */
public getTopUpThresholdAmount(): number {
    const topUpAmount = parseFloat(this.topUpAmount);
    if (isNaN(topUpAmount)) {
        return 0;
    }
    const threshold = parseFloat(this.topUpThreshold ? this.topUpThreshold : DEFAULT_TOP_UP_THRESHOLD);
    return topUpAmount * (isNaN(threshold) ? parseFloat(DEFAULT_TOP_UP_THRESHOLD) : threshold);
}

/**
 * Tops up the wallet of a customer enrolled in a prepaid credit (`topUp`) offering.
 *
 * The wallet is only topped up when the current balance of the wallet has dropped below
 * `topUpThreshold * topUpAmount`. When the wallet needs to be topped up, an invoice is created for
 * the difference between the current balance and the `topUpAmount`. The payment of that invoice is
 * stored as credit on the customers wallet.
 */
public async topUp({ customer }: { customer?: ReadCustomerResponseData }): Promise<string | void> {
    if (!this.isTopUpOffering() || !this.topUpAmount) {
        Offering.logger.log(
            `Offering ${this.offeringId} is not a top up offering, skipping top up for customer ${
                customer?.customerId ? customer?.customerId : this.customerId
            }`,
        );
        return;
    }
    const customerId = customer?.customerId ? customer?.customerId : this.customerId;
    const topUpAmount = parseFloat(this.topUpAmount);
    const currentBalance = Offering.getCustomerWalletBalance(customer);
    const thresholdAmount = this.getTopUpThresholdAmount();
    Offering.logger.log(
        `Evaluating top up for customer ${customerId}. Balance: ${currentBalance}, threshold: ${thresholdAmount}, top up amount: ${topUpAmount}`,
    );
    if (currentBalance >= thresholdAmount) {
        Offering.logger.log(
            `Customer ${customerId} has a sufficient wallet balance of ${currentBalance}, no top up required`,
        );
        return;
    }
    const amountToCharge = Number((topUpAmount - currentBalance).toFixed(2));
    const lineItems = new InvoiceLineItems();
    lineItems.addLineItem(new InvoiceLineItem(`${this.offeringName} - Top Up`, 1, amountToCharge));
    const { invoiceId } = await this.invoicesService.create({
        businessID: this.businessID,
        customer,
        customerId,
        items: lineItems,
        invoiceDate: new Date().toISOString(),
        currency: Offering.getCurrency({ customer, offering: this }),
        storePaymentAsCredit: true,
    });
    Offering.logger.log(`Created top up invoice ${invoiceId} for customer ${customerId} of ${amountToCharge}`);
    return invoiceId;
}

/**
 * Processes the usage of a customer enrolled in a prepaid credit (`topUp`) offering.
 *
 * The usage which occurred in the given time range is deducted from the customers wallet as a single
 * wallet transaction. No usage invoice is generated for a top up offering. After the usage has been
 * deducted the wallet is evaluated, and topped up if needed.
 */
public async processTopUpBilling({
    customer,
    creditService,
    startDate,
    endDate,
}: {
    customer?: ReadCustomerResponseData;
    creditService?: CreditService;
    startDate?: Date;
    endDate?: Date;
}): Promise<string | void> {
    const customerId = customer?.customerId ? customer?.customerId : this.customerId;
    const walletService = creditService ? creditService : this.creditService;
    const end = endDate ? endDate : new Date();
    const start = startDate ? startDate : new Date(end.getTime() - Offering.ONE_HOUR_IN_MS);
    const lineItems = await Offering.getLineItemsForUsage({
        startDate: start,
        endDate: end,
        customer,
        lineItems: new InvoiceLineItems(),
        negative: false,
        businessID: this.businessID,
        customerId,
        customerService: this.customerService,
        offeringInstance: this,
        dimensions: this.dimensions,
    });
    const usageTotal = Number(lineItems.getTotal().toFixed(2));
    Offering.logger.log(
        `Usage total for customer ${customerId} between ${start.toISOString()} and ${end.toISOString()} is ${usageTotal}`,
    );
    if (usageTotal > 0) {
        if (walletService) {
            // The full amount of usage is always deducted from the wallet, even when the usage
            // exceeds the current balance of the wallet.
            await walletService.create(
                {
                    transactionAmount: (usageTotal * -1).toFixed(2),
                    customerId,
                    businessID: this.businessID,
                    timestamp: end.toISOString(),
                    metadata: {
                        reason: `Usage for ${this.offeringName}`,
                        offeringId: this.offeringId,
                    },
                },
                false,
                true,
            );
        } else {
            AuditService.publishEvent({
                message: 'No credit service available to deduct top up usage from the customer wallet',
                topic: AuditScope.ERROR,
                data: [{ customerId, businessID: this.businessID, offeringId: this.offeringId, usageTotal }],
            });
        }
        const updatedBalance = Number((Offering.getCustomerWalletBalance(customer) - usageTotal).toFixed(2));
        if (customer) {
            customer.creditBalance = updatedBalance.toString();
        }
    }
    return this.topUp({ customer });
}

