/**
 * Validates that the prepaid credit top up fields are used correctly.
 * A `topUpAmount` is required for offerings with a `topUp` billing cycle, the top up fields are not
 * allowed on any other billing cycle, and subscription offerings cannot use the `topUp` billing cycle.
 */
public static validateTopUpFields({
    billingCycle,
    offeringType,
    topUpAmount,
    topUpThreshold,
}: {
    billingCycle?: ValidBillingCycles;
    offeringType?: string;
    topUpAmount?: string;
    topUpThreshold?: string;
}): void {
    const setBillingCycle = billingCycle ? billingCycle : ValidBillingCycles.monthly;
    if (setBillingCycle === ValidBillingCycles.topUp) {
        if (offeringType === OfferingType.subscription) {
            throw new BadRequestException(TOP_UP_NOT_ALLOWED_ON_SUBSCRIPTION_MESSAGE);
        }
        if (!topUpAmount) {
            throw new BadRequestException(TOP_UP_AMOUNT_REQUIRED_MESSAGE);
        }
    } else if (topUpAmount || topUpThreshold) {
        throw new BadRequestException(TOP_UP_FIELDS_NOT_ALLOWED_MESSAGE);
    }
}

