import { CustomerService } from '../../customer/customer.service.js';
import { paymentChannel } from '../../customer/dto/create-customer.dto.js';
import { ReadCustomerResponseData } from '../../customer/entities/customer.entity.js';
import { InvoicesService } from '../../invoice/invoices.service.js';
import { SchedulerService } from '../../scheduler/scheduler.service.js';
import { SupportedMeasurementFrequencies } from '../../scheduler/dto/scheduler.dto.js';
import { CreditService } from '../../credit/credit.service.js';
import { ReadSettingsResponseData } from '../../setting/dto/read-setting.dto.js';
import { FreeDimensionOnInvoice } from '../../setting/dto/FreeDimensionOnInvoice.js';
import { ValidBillingCycles } from '../dto/createOffering.dto.js';
import { ReadOfferingResponseData } from '../dto/readOffering.dto.js';
import { SupportedCurrencies } from '../dto/SupportedCurrencies.js';
import { Offering, OfferingPackageEntity, UsageBased } from './offeringPackage.entity.js';
import { OfferingType } from './OfferingType.js';
import {
    aggregationInterval,
    aggregationMethod,
    countBasedUnits,
    roundingEnum,
} from '../../dimensions/dto/create-dimension.dto.js';

describe('Top up offerings', () => {
    let invoicesService: InvoicesService;
    let customerService: CustomerService;
    let schedulerService: SchedulerService;
    let creditService: CreditService;
    const fakeBusinessID = 'fakeBusinessID';
    const fakeCustomerID = 'fakeCustomerID';
    const fakeOfferingId = 'fakeOfferingId';
    const fakeSettings = { freeDimensionOnInvoice: FreeDimensionOnInvoice.show } as ReadSettingsResponseData;
    let topUpOfferingConfig: ReadOfferingResponseData;
    let customer: ReadCustomerResponseData;

    const buildOffering = (overrides: Partial<ReadOfferingResponseData> = {}): UsageBased =>
        Offering.getInstance(
            { ...topUpOfferingConfig, ...overrides },
            fakeCustomerID,
            fakeBusinessID,
            invoicesService,
            fakeSettings,
            schedulerService,
            customerService,
            undefined,
            undefined,
            creditService,
        ) as UsageBased;

    beforeAll(() => {
        //eslint-disable-next-line
        //@ts-ignore
        invoicesService = new InvoicesService();
        //eslint-disable-next-line
        //@ts-ignore
        customerService = new CustomerService();
        //eslint-disable-next-line
        //@ts-ignore
        schedulerService = new SchedulerService();
        //eslint-disable-next-line
        //@ts-ignore
        creditService = new CreditService();
    });

    beforeEach(() => {
        //eslint-disable-next-line
        //@ts-ignore
        jest.spyOn(invoicesService, 'create').mockImplementation(async () => ({
            invoiceId: 'topUpInvoiceId',
            message: 'created',
        }));
        jest.spyOn(invoicesService, 'queueInvoice').mockImplementation(async () => ({ message: 'queued' }));
        //eslint-disable-next-line
        //@ts-ignore
        jest.spyOn(customerService, 'findUsageForCustomer').mockImplementation(async () => ({ data: [] }));
        //eslint-disable-next-line
        //@ts-ignore
        jest.spyOn(creditService, 'create').mockImplementation(async () => ({ message: 'created' }));
        //eslint-disable-next-line
        //@ts-ignore
        jest.spyOn(schedulerService, 'create').mockImplementation(async () => ({}));
        topUpOfferingConfig = {
            offeringId: fakeOfferingId,
            offeringName: 'Cool Offering',
            offeringType: OfferingType.usageBased,
            currency: SupportedCurrencies.USD,
            billingCycle: ValidBillingCycles.topUp,
            topUpAmount: '100',
            dimensions: [
                {
                    dimensionId: 'dimensionId',
                    dimensionName: 'Requests',
                    aggregationInterval: aggregationInterval.day,
                    aggregationMethod: aggregationMethod.sum,
                    usageIncrement: '1',
                    consumptionUnit: { unit: countBasedUnits['count-based'], type: 'count' },
                    rounding: roundingEnum.ceiling,
                    consumptionPrice: '1',
                },
            ],
        } as unknown as ReadOfferingResponseData;
        customer = {
            customerId: fakeCustomerID,
            customerName: 'fakeCustomerName',
            paymentChannel: paymentChannel.manual,
            businessID: fakeBusinessID,
            currency: SupportedCurrencies.USD,
            email: 'fakeEmail',
            creditBalance: '100',
        } as ReadCustomerResponseData;
    });

    afterEach(() => {
        jest.clearAllMocks();
    });

    it('defaults the top up threshold to 0.2', () => {
        const offering = buildOffering();
        expect(offering.topUpAmount).toEqual('100');
        expect(offering.topUpThreshold).toEqual('0.2');
        expect(offering.getTopUpThresholdAmount()).toEqual(20);
        expect(offering.isTopUpOffering()).toEqual(true);
    });

    it('persists the top up fields on the offering document', () => {
        const tag = jest.fn();
        const influxService = {
            getPoint: () => ({ tag, stringField: jest.fn() }),
            //eslint-disable-next-line
            //@ts-ignore
        } as unknown as Parameters<typeof OfferingPackageEntity.transformer>[1];
        const entity = new OfferingPackageEntity({
            offeringName: 'Cool Offering',
            businessID: fakeBusinessID,
            offeringId: fakeOfferingId,
            billingCycle: ValidBillingCycles.topUp,
            topUpAmount: '100',
        } as OfferingPackageEntity);
        expect(entity.topUpThreshold).toEqual('0.2');
        OfferingPackageEntity.transformer(entity, influxService);
        expect(tag).toHaveBeenCalledWith('billingCycle', ValidBillingCycles.topUp);
        expect(tag).toHaveBeenCalledWith('topUpAmount', '100');
        expect(tag).toHaveBeenCalledWith('topUpThreshold', '0.2');
        const readEntity = OfferingPackageEntity.dbModelToEntity({
            _value: 'Cool Offering',
            businessID: fakeBusinessID,
            offeringId: fakeOfferingId,
            billingCycle: ValidBillingCycles.topUp,
            offeringType: OfferingType.usageBased,
            subscriptionPrice: '0',
            topUpAmount: '100',
            topUpThreshold: '0.2',
        });
        expect(readEntity.topUpAmount).toEqual('100');
        expect(readEntity.topUpThreshold).toEqual('0.2');
    });

    it('does not top up a wallet which is exactly at the threshold', async () => {
        const offering = buildOffering();
        await offering.topUp({ customer: { ...customer, creditBalance: '20' } });
        expect(invoicesService.create).toHaveBeenCalledTimes(0);
    });

    it('tops up a wallet which is below the threshold with the difference to the top up amount', async () => {
        const offering = buildOffering();
        const invoiceId = await offering.topUp({ customer: { ...customer, creditBalance: '19.99' } });
        expect(invoiceId).toEqual('topUpInvoiceId');
        expect(invoicesService.create).toHaveBeenCalledTimes(1);
        const [[input]] = (invoicesService.create as jest.Mock).mock.calls;
        expect(input.storePaymentAsCredit).toEqual(true);
        expect(input.businessID).toEqual(fakeBusinessID);
        expect(input.customerId).toEqual(fakeCustomerID);
        expect(input.items.getLineItems()).toEqual([
            { name: 'Cool Offering - Top Up', quantity: 1, unitCost: 80.01, description: undefined },
        ]);
    });

    it('registers a single hourly offering level scheduler and tops up on enrollment', async () => {
        const offering = buildOffering();
        await offering.enroll('subject', { ...customer, creditBalance: '0' });
        expect(schedulerService.create).toHaveBeenCalledTimes(1);
        const [[schedulerInput]] = (schedulerService.create as jest.Mock).mock.calls;
        expect(schedulerInput.rate).toEqual(SupportedMeasurementFrequencies.everyHour);
        expect(schedulerInput.schedulerID).toEqual(fakeOfferingId);
        expect(schedulerInput.schedulerID).not.toContain(fakeCustomerID);
        expect(schedulerInput.scheduleParameters).toEqual(
            expect.objectContaining({ businessID: fakeBusinessID, offeringId: fakeOfferingId }),
        );
        expect(invoicesService.create).toHaveBeenCalledTimes(1);
        const [[input]] = (invoicesService.create as jest.Mock).mock.calls;
        expect(input.items.getLineItems()).toEqual([
            { name: 'Cool Offering - Top Up', quantity: 1, unitCost: 100, description: undefined },
        ]);
    });

    it('deducts hourly usage from the wallet and does not create a usage invoice', async () => {
        //eslint-disable-next-line
        //@ts-ignore
        jest.spyOn(customerService, 'findUsageForCustomer').mockImplementation(async () => ({
            data: [{ dimensionId: 'dimensionId', usage: [{ value: '30' }] }],
        }));
        const offering = buildOffering();
        const walletCustomer = { ...customer, creditBalance: '100' };
        await offering.processTopUpBilling({ customer: walletCustomer });
        expect(creditService.create).toHaveBeenCalledTimes(1);
        expect(creditService.create).toHaveBeenCalledWith(
            expect.objectContaining({ transactionAmount: '-30.00', customerId: fakeCustomerID }),
            false,
            true,
        );
        // The in memory balance is updated so the top up is evaluated against the new balance
        expect(walletCustomer.creditBalance).toEqual('70');
        expect(invoicesService.create).toHaveBeenCalledTimes(0);
    });

    it('tops up the wallet after the hourly usage has dropped the balance below the threshold', async () => {
        //eslint-disable-next-line
        //@ts-ignore
        jest.spyOn(customerService, 'findUsageForCustomer').mockImplementation(async () => ({
            data: [{ dimensionId: 'dimensionId', usage: [{ value: '90' }] }],
        }));
        const offering = buildOffering();
        const walletCustomer = { ...customer, creditBalance: '100' };
        await offering.processBilling(undefined, undefined, walletCustomer);
        expect(creditService.create).toHaveBeenCalledTimes(1);
        expect(creditService.create).toHaveBeenCalledWith(
            expect.objectContaining({ transactionAmount: '-90.00' }),
            false,
            true,
        );
        expect(walletCustomer.creditBalance).toEqual('10');
        expect(invoicesService.create).toHaveBeenCalledTimes(1);
        const [[input]] = (invoicesService.create as jest.Mock).mock.calls;
        expect(input.items.getLineItems()).toEqual([
            { name: 'Cool Offering - Top Up', quantity: 1, unitCost: 90, description: undefined },
        ]);
    });

    it('deducts usage which is greater than the current balance of the wallet', async () => {
        //eslint-disable-next-line
        //@ts-ignore
        jest.spyOn(customerService, 'findUsageForCustomer').mockImplementation(async () => ({
            data: [{ dimensionId: 'dimensionId', usage: [{ value: '150' }] }],
        }));
        const offering = buildOffering();
        const walletCustomer = { ...customer, creditBalance: '100' };
        await offering.processTopUpBilling({ customer: walletCustomer });
        expect(creditService.create).toHaveBeenCalledWith(
            expect.objectContaining({ transactionAmount: '-150.00' }),
            false,
            true,
        );
        expect(walletCustomer.creditBalance).toEqual('-50');
        expect(invoicesService.create).toHaveBeenCalledTimes(1);
        const [[input]] = (invoicesService.create as jest.Mock).mock.calls;
        expect(input.items.getLineItems()).toEqual([
            { name: 'Cool Offering - Top Up', quantity: 1, unitCost: 150, description: undefined },
        ]);
    });

    it('evaluates the top up without creating a wallet transaction when there is no usage', async () => {
        const offering = buildOffering();
        const walletCustomer = { ...customer, creditBalance: '5' };
        await offering.processTopUpBilling({ customer: walletCustomer });
        expect(creditService.create).toHaveBeenCalledTimes(0);
        expect(walletCustomer.creditBalance).toEqual('5');
        expect(invoicesService.create).toHaveBeenCalledTimes(1);
        const [[input]] = (invoicesService.create as jest.Mock).mock.calls;
        expect(input.items.getLineItems()).toEqual([
            { name: 'Cool Offering - Top Up', quantity: 1, unitCost: 95, description: undefined },
        ]);
    });

    it('does not top up offerings which are not top up offerings', async () => {
        const offering = buildOffering({
            billingCycle: ValidBillingCycles.monthly,
            topUpAmount: undefined,
            topUpThreshold: undefined,
        });
        expect(offering.isTopUpOffering()).toEqual(false);
        await offering.topUp({ customer });
        expect(invoicesService.create).toHaveBeenCalledTimes(0);
    });
});

import { validate } from 'class-validator';
import { plainToInstance } from 'class-transformer';
import { CreateOfferingDTO, ValidBillingCycles } from './createOffering.dto.js';
import { OfferingType } from '../entities/OfferingType.js';
import { OfferingService } from '../offering.service.js';

const buildDto = (input: Partial<CreateOfferingDTO>): CreateOfferingDTO =>
    plainToInstance(CreateOfferingDTO, {
        offeringName: 'Cool Offering',
        offeringType: OfferingType.usageBased,
        ...input,
    });

describe('top up offering validation', () => {
    it('accepts a top up offering with a top up amount', async () => {
        const errors = await validate(
            buildDto({ billingCycle: ValidBillingCycles.topUp, topUpAmount: '100', topUpThreshold: '0.5' }),
        );
        expect(errors).toHaveLength(0);
        expect(() =>
            OfferingService.validateTopUpFields({
                billingCycle: ValidBillingCycles.topUp,
                offeringType: OfferingType.usageBased,
                topUpAmount: '100',
                topUpThreshold: '0.5',
            }),
        ).not.toThrow();
    });

    it('requires a top up amount for top up offerings', async () => {
        const errors = await validate(buildDto({ billingCycle: ValidBillingCycles.topUp }));
        expect(errors.length).toBeGreaterThan(0);
        expect(() =>
            OfferingService.validateTopUpFields({
                billingCycle: ValidBillingCycles.topUp,
                offeringType: OfferingType.usageBased,
            }),
        ).toThrow();
    });

    it('does not allow top up fields on other billing cycles', async () => {
        const errors = await validate(buildDto({ billingCycle: ValidBillingCycles.monthly, topUpAmount: '100' }));
        expect(errors.length).toBeGreaterThan(0);
        const thresholdErrors = await validate(
            buildDto({ billingCycle: ValidBillingCycles.annualToDate, topUpThreshold: '0.2' }),
        );
        expect(thresholdErrors.length).toBeGreaterThan(0);
